let eqGraph=null,eqCompare=false,eqFailure='',eqDrawTimer;
function dbGain(db){return Math.pow(10,db/20)}
function stereoMatrix(width){const w=width/100;return [(1+w)/2,(1-w)/2]}
function makeEqImpulse(ctx){const length=Math.round(ctx.sampleRate*1.3),b=ctx.createBuffer(2,length,ctx.sampleRate);let seed=12345;for(let channel=0;channel<2;channel++){const d=b.getChannelData(channel);for(let i=0;i<length;i++){seed=(seed*16807)%2147483647;d[i]=(seed/1073741823.5-1)*Math.pow(1-i/length,3)*.3}}return b}
const soundModes={studio:{speed:1,preservePitch:true,bass:0,depth:0,warmth:0,reverb:0},lofi:{speed:.96,preservePitch:true,bass:2,depth:1,warmth:3,reverb:18},nightcore:{speed:1.25,preservePitch:false,bass:0,depth:0,warmth:0,reverb:0},slowed:{speed:.85,preservePitch:false,bass:3,depth:2,warmth:1,reverb:15},vaporwave:{speed:.8,preservePitch:false,bass:2,depth:2,warmth:3,reverb:28}};
function activateEqEdit(){eqSettings.on=true;eqCompare=false;ensureEqGraph();eqGraph?.ctx.resume().catch(()=>{});if($('#eqEnabled'))$('#eqEnabled').checked=true;const compare=$('#eqCompare');if(compare){compare.textContent='Сравнить с оригиналом';compare.setAttribute('aria-pressed','false');compare.classList.remove('selected')}}
function ensureEqGraph(){if(eqGraph)return true;if(eqFailure)return false;let ctx,source;try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)throw Error('Web Audio недоступен');ctx=new Ctx();source=ctx.createMediaElementSource(audio);const pre=ctx.createGain(),bass=ctx.createBiquadFilter(),warm=ctx.createBiquadFilter(),input=ctx.createGain(),split=ctx.createChannelSplitter(2),merge=ctx.createChannelMerger(2),out=ctx.createGain();input.channelCount=2;input.channelCountMode='explicit';input.channelInterpretation='speakers';bass.type='lowshelf';bass.frequency.value=120;warm.type='highshelf';warm.frequency.value=6000;const bands=eqFrequencies.map(f=>{const n=ctx.createBiquadFilter();n.type='peaking';n.frequency.value=Math.min(f,ctx.sampleRate*.45);n.Q.value=eqSettings.q;return n});source.connect(pre);pre.connect(bass);let tail=bass;for(const n of bands){tail.connect(n);tail=n}tail.connect(warm);const depth=ctx.createBiquadFilter();depth.type='peaking';depth.frequency.value=60;depth.Q.value=.9;warm.connect(depth);depth.connect(input);input.connect(split);const matrix=[ctx.createGain(),ctx.createGain(),ctx.createGain(),ctx.createGain()];split.connect(matrix[0],0);matrix[0].connect(merge,0,0);split.connect(matrix[1],1);matrix[1].connect(merge,0,0);split.connect(matrix[2],0);matrix[2].connect(merge,0,1);split.connect(matrix[3],1);matrix[3].connect(merge,0,1);const dynamics=ctx.createDynamicsCompressor(),dry=ctx.createGain(),reverb=ctx.createConvolver(),wet=ctx.createGain();reverb.buffer=makeEqImpulse(ctx);merge.connect(dynamics);dynamics.connect(dry);dry.connect(out);dynamics.connect(reverb);reverb.connect(wet);wet.connect(out);const analyser=ctx.createAnalyser();analyser.fftSize=1024;out.connect(analyser);analyser.connect(ctx.destination);const probes=[...bands,bass,warm,depth].map(n=>{const p=ctx.createBiquadFilter();p.type=n.type;p.frequency.value=n.frequency.value;return p});eqGraph={ctx,source,pre,bass,warm,depth,bands,matrix,out,analyser,probes,dynamics,dry,reverb,wet,reduction:0};applyEq();ctx.resume().catch(()=>{});return true}catch(e){eqFailure=e.message||'Не удалось включить обработку звука';try{source?.disconnect();source?.connect(ctx.destination);ctx?.resume()}catch{}toast('Эквалайзер недоступен. Воспроизведение продолжается без эффектов.');return false}}
function smooth(param,value){const t=eqGraph.ctx.currentTime;param.cancelScheduledValues(t);param.setTargetAtTime(value,t,.025)}
function applyEq(){localStorage.setItem('soulroom.eq',JSON.stringify(eqSettings));const active=eqSettings.on&&!eqCompare;audio.playbackRate=active?eqSettings.speed:1;audio.preservesPitch=active?eqSettings.preservePitch:true;if(!eqGraph)return;const on=active,g=eqGraph;smooth(g.depth.gain,on?eqSettings.depth:0);smooth(g.wet.gain,on?eqSettings.reverb/100:0);smooth(g.dry.gain,1);smooth(g.dynamics.threshold,on&&eqSettings.normalize?-18:0);smooth(g.dynamics.knee,on&&eqSettings.normalize?18:0);smooth(g.dynamics.ratio,on&&eqSettings.normalize?3:1);smooth(g.dynamics.attack,.01);smooth(g.dynamics.release,.3);g.bands.forEach((n,i)=>{smooth(n.gain,on?eqSettings.bands[i]:0);smooth(n.Q,eqSettings.q)});smooth(g.bass.gain,on?eqSettings.bass:0);smooth(g.warm.gain,on?-eqSettings.warmth*1.5:0);const [a,b]=stereoMatrix(on?eqSettings.width:100);[a,b,b,a].forEach((v,i)=>smooth(g.matrix[i].gain,v));const f=new Float32Array(240),m=new Float32Array(240),p=new Float32Array(240),sum=new Array(240).fill(0);for(let i=0;i<240;i++)f[i]=20*Math.pow(Math.min(20000,g.ctx.sampleRate*.45)/20,i/239);g.probes.forEach((n,i)=>{n.Q.value=i===12?.9:eqSettings.q;n.gain.value=on?(i<10?eqSettings.bands[i]:i===10?eqSettings.bass:i===11?-eqSettings.warmth*1.5:eqSettings.depth):0;n.getFrequencyResponse(f,m,p);for(let j=0;j<240;j++)sum[j]+=20*Math.log10(Math.max(.00001,m[j]))});const extra=on?Math.max(0,...sum)+20*Math.log10(Math.max(1,eqSettings.width/100))+20*Math.log10(1+eqSettings.reverb/100):0;g.reduction=on&&eqSettings.safe?(extra+eqSettings.preamp>0?extra+eqSettings.preamp+.8:0):0;smooth(g.pre.gain,on?dbGain(eqSettings.preamp-g.reduction):1);if($('#eqReduction'))$('#eqReduction').textContent=g.reduction?`Запас по уровню: −${g.reduction.toFixed(1)} дБ`:'Исходный уровень';clearTimeout(eqDrawTimer);eqDrawTimer=setTimeout(drawEqCurve,160)}
function drawEqCurve(){const node=$('#eqCurve');if(!node)return;if(!eqGraph){node.innerHTML='<path d="M0 100H800" stroke="var(--accent)" stroke-width="2"/>';return}const f=new Float32Array(160),m=new Float32Array(160),phase=new Float32Array(160),db=new Array(160).fill(0);for(let i=0;i<160;i++)f[i]=Math.min(20000,eqGraph.ctx.sampleRate*.45)*Math.pow(20/Math.min(20000,eqGraph.ctx.sampleRate*.45),1-i/159);for(const filter of [...eqGraph.bands,eqGraph.bass,eqGraph.warm,eqGraph.depth]){filter.getFrequencyResponse(f,m,phase);for(let i=0;i<160;i++)db[i]+=20*Math.log10(Math.max(.0001,m[i]))}const points=db.map((v,i)=>`${i?'L':'M'}${(i*800/159).toFixed(1)} ${(100-Math.max(-18,Math.min(18,v))*4.5).toFixed(1)}`).join(' ');node.innerHTML=`<path d="M0 100H800M0 46H800M0 154H800" stroke="var(--line)" stroke-width="1"/><path d="${points} L800 200H0Z" fill="var(--accent)" opacity=".07"/><path d="${points}" fill="none" stroke="var(--accent)" stroke-width="2.5"/>`}
function eqScreen(){return ''+`<section class="eq-intro settings-card"><div><span class="eyebrow">SOULROOM / AUDIO LAB</span><h2>Услышь больше.</h2><p>Десять полос, тёплые оттенки и точное стерео.<br>Твои настройки действуют на весь звук плеера.</p></div><label class="eq-power"><input id="eqEnabled" type="checkbox" ${eqSettings.on?'checked':''}>Эквалайзер включён</label></section><section class="eq-modes"><div class="eq-mode-picks">${[['studio','Студия'],['lofi','Lo-Fi'],['nightcore','Nightcore'],['slowed','Slowed'],['vaporwave','Vaporwave']].map(([id,name])=>`<button data-sound-mode="${id}" class="${eqSettings.mode===id?'selected':''}">${name}</button>`).join('')}</div><label class="eq-speed-control"><span>Скорость</span><output id="eq-speed">${eqSettings.speed.toFixed(2)}×</output><input type="range" data-eq-setting="speed" aria-label="Скорость воспроизведения" min=".5" max="1.5" step=".05" value="${eqSettings.speed}"></label><label class="eq-pitch-control"><input id="eqPreservePitch" type="checkbox" ${eqSettings.preservePitch?'checked':''}>Сохранять высоту тона</label></section><div class="eq-presets">${Object.entries(eqPresets).map(([id,p])=>`<button class="secondary ${eqSettings.preset===id?'selected':''}" data-eq-preset="${id}">${p.name}</button>`).join('')}</div><section class="settings-card eq-console"><div class="section-head"><h2>Частоты</h2><span>20 Гц — 20 кГц</span></div><svg id="eqCurve" class="eq-curve" viewBox="0 0 800 200" preserveAspectRatio="none" aria-label="АЧХ фильтров без предусиления"></svg><div class="eq-bands">${eqFrequencies.map((hz,i)=>`<label><output id="eqOut${i}">${eqSettings.bands[i]>0?'+':''}${eqSettings.bands[i]}</output><input type="range" data-eq-band="${i}" aria-label="Полоса ${hz} Гц" min="-12" max="12" step=".5" value="${eqSettings.bands[i]}"><span>${hz>=1000?hz/1000+'k':hz}</span></label>`).join('')}</div><div class="eq-level"><span>Выходной уровень</span><meter id="eqMeter" min="-60" max="0" value="-60" aria-label="Выходной уровень звука"></meter><output id="eqMeterValue">−∞ дБFS</output></div><div class="eq-comparison"><span>±12 дБ · плавное изменение</span><button class="secondary ${eqCompare?'selected':''}" id="eqCompare" aria-pressed="${eqCompare}">${eqCompare?'Вернуть обработку':'Сравнить с оригиналом'}</button></div></section><section class="settings-card eq-adjustments"><h3>Характер и уровень</h3>${[['preamp','Предусиление',-12,6,.5,' дБ'],['q','Ширина полос (Q)',.5,2,.1,''],['bass','Низкие частоты',0,8,.5,' дБ'],['depth','Глубина',-6,8,.5,' дБ'],['reverb','Реверберация',0,60,1,'%'],['warmth','Теплота',0,4,.5,''],['width','Ширина стерео',0,150,5,'%']].map(([k,name,min,max,step,unit])=>`<label><span>${name}</span><output id="eq-${k}">${eqSettings[k]}${unit}</output><input type="range" data-eq-setting="${k}" aria-label="${name}" min="${min}" max="${max}" step="${step}" value="${eqSettings[k]}"></label>`).join('')}<label class="eq-safe"><span>Сглаживать перепады громкости</span><input type="checkbox" id="eqNormalize" ${eqSettings.normalize?'checked':''}></label><label class="eq-safe"><span>Автоматический запас по уровню</span><input type="checkbox" id="eqSafe" ${eqSettings.safe?'checked':''}></label><p id="eqReduction">${eqGraph?.reduction?'Запас по уровню: −'+eqGraph.reduction.toFixed(1)+' дБ':'Защита уменьшает уровень при усилении частот.'}</p><p>Ширина 100% сохраняет исходное стерео, 0% — моно. Выключение возвращает исходный сигнал. АЧХ показывает фильтры до предусиления.</p><button class="secondary" id="eqReset">Сбросить звук</button>${eqFailure?`<p>${esc(eqFailure)}</p>`:''}</section>`}
const renderBeforeEq=render;render=function(){renderBeforeEq();if(page==='equalizer'){$('#crumb').textContent='ЗВУК';$('#view').innerHTML=eqScreen();drawEqCurve()}};
const eqDialog=document.createElement('dialog');eqDialog.className='eq-dialog';eqDialog.setAttribute('aria-label','Эквалайзер');document.body.append(eqDialog);
