const eqDockButton=document.createElement('button');eqDockButton.dataset.openEq='';eqDockButton.id='eqDockButton';eqDockButton.title='Эквалайзер';eqDockButton.setAttribute('aria-label','Эквалайзер');eqDockButton.innerHTML=playerIcon('sliders');document.querySelector('.player-right').prepend(eqDockButton);
