eqDialog.addEventListener('click',e=>{if(e.target===eqDialog){const r=eqDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)eqDialog.close()}});
