document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.eqPreset){eqSettings=cleanEq({...eqSettings,on:true,preset:b.dataset.eqPreset,bands:eqPresets[b.dataset.eqPreset].bands,preamp:0,bass:0,warmth:0,width:100});eqCompare=false;ensureEqGraph();applyEq();refreshEqSurface()}if(b.id==='eqCompare'){eqCompare=!eqCompare;applyEq();refreshEqSurface()}if(b.id==='eqReset'){eqSettings=cleanEq({preset:'flat',on:false});eqCompare=false;applyEq();refreshEqSurface()}},false);
document.addEventListener('input',e=>{const i=e.target.dataset.eqBand,k=e.target.dataset.eqSetting;if(i!==undefined){eqSettings.bands[+i]=+e.target.value;eqSettings.preset='custom';$('#eqOut'+i).textContent=(+e.target.value>0?'+':'')+e.target.value}if(k){eqSettings=cleanEq({...eqSettings,[k]:+e.target.value});$('#eq-'+k).textContent=e.target.value+(k==='speed'?'×':['width','reverb'].includes(k)?'%':['preamp','bass','depth'].includes(k)?' дБ':'')}if(i!==undefined||k){activateEqEdit();applyEq();document.querySelectorAll('[data-eq-preset]').forEach(n=>n.classList.toggle('selected',eqSettings.preset===n.dataset.eqPreset))}});
document.addEventListener('change',e=>{if(e.target.id==='eqEnabled'){eqSettings.on=e.target.checked;eqCompare=false;if(eqSettings.on)ensureEqGraph();applyEq()}if(e.target.id==='eqSafe'){eqSettings.safe=e.target.checked;applyEq()}});
document.addEventListener('click',e=>{if(eqSettings.on&&(e.target.closest('#play,#focusPlay,[data-track],[data-room],[data-mood],[data-focus-next]'))){ensureEqGraph();eqGraph?.ctx.resume().catch(()=>{})}},true);audio.addEventListener('play',()=>{if(eqSettings.on)ensureEqGraph();eqGraph?.ctx.resume().catch(()=>{})});

setInterval(()=>{if((page!=='equalizer'&&!eqDialog.open)||!$('#eqMeter'))return;let db=-60;if(eqGraph&&eqGraph.ctx.state==='running'&&!audio.paused){const values=new Float32Array(eqGraph.analyser.fftSize);eqGraph.analyser.getFloatTimeDomainData(values);const rms=Math.sqrt(values.reduce((sum,x)=>sum+x*x,0)/values.length);db=Math.max(-60,Math.min(0,20*Math.log10(Math.max(.000001,rms))))}$('#eqMeter').value=db;$('#eqMeterValue').textContent=db<=-60?'−∞ дБFS':db.toFixed(1)+' дБFS'},150);

document.addEventListener('click',e=>{const b=e.target.closest('[data-sound-mode]');if(!b)return;const mode=b.dataset.soundMode;const curves={lofi:[2,3,2,0,-1,-3,-5,-7,-8,-9],nightcore:[-2,-1,0,1,2,3,4,5,5,4],slowed:[4,5,4,2,0,-1,-2,-3,-3,-2],vaporwave:[3,4,3,0,-2,-4,-5,-6,-6,-5]};
if(eqSettings.mode==='studio'&&mode!=='studio')localStorage.setItem('soulroom.studioEq',JSON.stringify(eqSettings));
if(mode==='studio'){
 let saved;try{saved=JSON.parse(localStorage.getItem('soulroom.studioEq'))}catch{}
 eqSettings=cleanEq({...eqSettings,...soundModes.studio,...saved,mode,on:true});
}else eqSettings=cleanEq({...eqSettings,...soundModes[mode],mode,on:true,bands:curves[mode],preset:'custom'});activateEqEdit();applyEq();refreshEqSurface()});
document.addEventListener('change',e=>{if(e.target.id==='eqPreservePitch'){eqSettings.preservePitch=e.target.checked;activateEqEdit();applyEq()}if(e.target.id==='eqNormalize'){eqSettings.normalize=e.target.checked;activateEqEdit();applyEq()}});
